CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','student')),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE courses(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,demo INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE enrollments(user_id BIGINT REFERENCES users(id),course_id BIGINT REFERENCES courses(id),PRIMARY KEY(user_id,course_id));
CREATE TABLE materials(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,course_id BIGINT NOT NULL REFERENCES courses(id),title TEXT NOT NULL,kind TEXT NOT NULL,content TEXT NOT NULL,filename TEXT,mime TEXT);
CREATE TABLE leads(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,course_id BIGINT REFERENCES courses(id),message TEXT,status TEXT NOT NULL DEFAULT 'novo',consent_at TEXT NOT NULL,privacy_snapshot TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor BIGINT REFERENCES users(id),action TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE attempts(key TEXT NOT NULL,created DOUBLE PRECISION NOT NULL);
CREATE INDEX attempts_lookup ON attempts(key,created);
CREATE TABLE course_photos(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,course_id BIGINT NOT NULL REFERENCES courses(id),filename TEXT NOT NULL,caption TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE INDEX course_photo_order ON course_photos(course_id,sort_order,id);
CREATE TABLE announcements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',filename TEXT NOT NULL,link TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
